import{_ as o,C as e,c as d,o as s,j as a,G as l,ak as c,a as p}from"./chunks/framework.D7ejh1zC.js";const y=JSON.parse('{"title":"网络分层模型","description":"","frontmatter":{},"headers":[],"relativePath":"module/network/网络分层模型.md","filePath":"concept/module/network/网络分层模型.md","lastUpdated":1786880804000}'),P={name:"module/network/网络分层模型.md"};function h(g,t,_,m,x,T){const n=e("mdInfo"),i=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return s(),d("div",null,[t[0]||(t[0]=a("h1",{id:"网络分层模型",tabindex:"-1"},[p("网络分层模型 "),a("a",{class:"header-anchor",href:"#网络分层模型","aria-label":'Permalink to "网络分层模型"'},"​")],-1)),l(n),t[1]||(t[1]=c('<h2 id="网络分层模型五层网络模型" tabindex="-1">网络分层模型五层网络模型 <a class="header-anchor" href="#网络分层模型五层网络模型" aria-label="Permalink to &quot;网络分层模型五层网络模型&quot;">​</a></h2><p>经过不断演化，网络最终形成五层模型：</p><table tabindex="0"><thead><tr><th style="text-align:center;">分层</th><th style="text-align:center;">协议</th><th style="text-align:center;">功能</th></tr></thead><tbody><tr><td style="text-align:center;">应用层</td><td style="text-align:center;">HTTP、FTP、DNS、SMTP、POP3</td><td style="text-align:center;">网络应用到具体场景，不同场景建立不同协议来应对不同事情。</td></tr><tr><td style="text-align:center;">传输层</td><td style="text-align:center;">TCP、UDP</td><td style="text-align:center;">数据怎么传输，如何保证消息可靠传递。TCP 是可靠传输协议，数据包传输时出错了 TCP 会自动纠错；UDP 是广播协议，直播用的是 UDP，如果卡顿过了就过了，不是很可靠。</td></tr><tr><td style="text-align:center;">网络层</td><td style="text-align:center;">IP、路由器</td><td style="text-align:center;">如何在互联网中找到对方，通过 IP 地址定位对方。</td></tr><tr><td style="text-align:center;">数据链路层</td><td style="text-align:center;">交换机、MAC</td><td style="text-align:center;">如何在子网中如何找到对方的 MAC 地址，MAC 地址相当于电脑的指纹，出生就固定了。</td></tr><tr><td style="text-align:center;">物理层</td><td style="text-align:center;">光纤、集线器</td><td style="text-align:center;">不同设备之间的信息交互传输协议，如使用什么信号来传输，电信号还是光信号，光信号用什么波，电信号的波峰和波普等。</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">注意</p><p>IP 地址和 MAC 地址是两个不同的概念，IP 地址是网络层协议，MAC 地址是数据链路层协议。IP 地址是动态唯一，同一台设备有可能会变化；MAC 地址是静态唯一。</p></div><h2 id="网络分层模型数据的传输" tabindex="-1">网络分层模型数据的传输 <a class="header-anchor" href="#网络分层模型数据的传输" aria-label="Permalink to &quot;网络分层模型数据的传输&quot;">​</a></h2><p>数据在传输中，发送方从上往下，是封装的过程，每一层都会加上自己的协议头等而外的信息；接收方从下往上，是解封装的过程，每一层都认识各自的信息，会去掉自己的协议头。</p><p><img src="http://mdrs.yuanjin.tech/img/20211008163458.png" alt="数据的传输过程" loading="lazy"></p><p>从发送方开始，发送方发送一条文本数据，会经过以下步骤：</p><ol><li>应用层，将文本数据封装成 HTTP 协议，发送给传输层。</li><li>传输层，将 HTTP 协议封装成 TCP 协议，发送给网络层。</li><li>网络层，将 TCP 协议封装成 IP 协议，发送给数据链路层。</li><li>数据链路层，将 IP 协议封装成 MAC 协议，发送给物理层。</li><li>物理层，将 MAC 协议转换为相应的信号发送给接收方。</li></ol><p>接收方收到数据后，会经过以下步骤：</p><ol><li>物理层，将信号转换为 MAC 协议，发送给数据链路层。</li><li>数据链路层，将 MAC 协议解封装成 IP 协议，发送给网络层。</li><li>网络层，将 IP 协议解封装成 TCP 协议，发送给传输层。</li><li>传输层，将 TCP 协议解封装成 HTTP 协议，发送给应用层。</li><li>应用层，将 HTTP 协议解封装成文本数据，供应用使用。</li></ol><h2 id="网络分层模型四层五层七层" tabindex="-1">网络分层模型四层五层七层 <a class="header-anchor" href="#网络分层模型四层五层七层" aria-label="Permalink to &quot;网络分层模型四层五层七层&quot;">​</a></h2><p>最早的时候，官方标准还没形成，民间因为各自的需求，而自发约定了各种说法，比如四层、五层、七层等。</p><p><img src="http://mdrs.yuanjin.tech/img/20211008164017.png" alt="数据的传输过程" loading="lazy"></p><ul><li><p>四层模型：应用层、传输层、网络层、物理链路层</p><p>物理链路层为数据链路层、物理层的合并。</p></li><li><p>七层模型：应用层、表示层、会话层、传输层、网络层、数据链路层、物理层</p><p>表示层、会话层和应用层关系密切，没必要分这么细致，对于实际应用开发帮助不大，因此日常并不承认，只存在教科书上。</p></li><li><p>五层模型：应用层、传输层、网络层、数据链路层、物理层</p></li></ul>',15)),l(i),l(r)])}const u=o(P,[["render",h]]);export{y as __pageData,u as default};
